def sliding_totals(nums, width):
    if width < 1:
        raise ValueError("width must be >= 1")
    if width > len(nums):
        return []
    running = sum(nums[:width])
    totals = [running]
    for i in range(width, len(nums)):
        running += nums[i] - nums[i - width]
        totals.append(running)
    return totals

